    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    adds  x9, x3, x3
    adcs  x10, x4, x4
    adcs  x11, x5, x5
    adcs  x12, x6, x6
    adcs  x13, x7, x7
    adc   x14, x8, x8
    stp   x9, x10, [sp, #48]
    stp   x11, x12, [sp, #64]
    stp   x13, x14, [sp, #80]
    // s = a0 + a1 (raw) -> [sp]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldp   x13, x14, [x1, #80]
    adds  x9, x9, x3
    adcs  x10, x4, x10
    adcs  x11, x5, x11
    adcs  x12, x6, x12
    adcs  x13, x7, x13
    adc   x14, x14, x8
    stp   x9, x10, [sp]
    stp   x11, x12, [sp, #16]
    stp   x13, x14, [sp, #32]
    // d = a0 - a1 + 2p (raw) -> x3..x8 ; p2 = 2p = {-2,-1,...,0x000000000000005F}
    ldp   x9, x10, [x1, #48]
    subs  x3, x3, x9
    sbcs  x4, x4, x10
    ldp   x9, x10, [x1, #64]
    sbcs  x5, x5, x9
    sbcs  x6, x6, x10
    ldp   x9, x10, [x1, #80]
    sbcs  x7, x7, x9
    sbcs  x8, x8, x10
    mov   x9, #-2
    adds  x3, x3, x9
    mov   x9, #-1
    adcs  x4, x4, x9
    adcs  x5, x5, x9
    adcs  x6, x6, x9
    adcs  x7, x7, x9
    movz  x9, #0x005f                // 2p[5]
    adc   x8, x8, x9

    // [x9:x15] <- z = d x s0
    ldr   x16, [sp]
    MUL64x384  x9,x10,x11,x12,x13,x14,x15, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  sp, x3,x4,x5,x6,x7,x8, x9,x10,x11,x12,x13,x14,x15, x16, x17

    // c0 -> [x0] (a0's slot; a1 is still intact if c == a)
    stp   x15, x9, [x0]
    stp   x10, x11, [x0, #16]
    stp   x12, x13, [x0, #32]

    // [x15, x9:x14] <- z = a1 x t0
    ldp   x3, x4, [x1, #48]
    ldp   x5, x6, [x1, #64]
    ldp   x7, x8, [x1, #80]
    add   x1, sp, #48                // x1 is dead after the a1 load: reuse it as the t pointer
    ldr   x16, [x1]
    MUL64x384  x15,x9,x10,x11,x12,x13,x14, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  x1, x3,x4,x5,x6,x7,x8, x15,x9,x10,x11,x12,x13,x14, x16, x17

    stp   x14, x15, [x0, #48]
    stp   x9, x10, [x0, #64]
    stp   x11, x12, [x0, #80]
    add   sp, sp, #96
    ret

//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x8;
//                       acc z0..z6 = x9..x15,
//                       scalar bi = x16, MULADD temp x17;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global fp_mul
.p2align 6
fp_mul:
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]

    // [x9:x15] <- z = a x b0
    ldr   x16, [x2]
    MUL64x384  x9,x10,x11,x12,x13,x14,x15, x3,x4,x5,x6,x7,x8, x16, x17
    FPMUL384x384  x2, x3,x4,x5,x6,x7,x8, x9,x10,x11,x12,x13,x14,x15, x16, x17

    stp   x15, x9, [x0]
    stp   x10, x11, [x0, #16]
    stp   x12, x13, [x0, #32]
    ret

.global fp_sqr
.p2align 6
fp_sqr:
    mov   x2, x1
    b     fp_mul
